// Construit la requête POST /search de chaque texte suivi, d'après les exemples officiels
// de la DILA (« Utilisation de l'API Légifrance : exemples de cas pratique », 17/09/2025).
const maintenant = Date.now();
const critere = (typeChamp, valeur) => ({
  typeChamp,
  criteres: [{ typeRecherche: 'EXACTE', valeur, operateur: 'ET' }],
  operateur: 'ET',
});
const dateVersion = { facette: 'DATE_VERSION', singleDate: maintenant };
const enVigueur = { facette: 'TEXT_LEGAL_STATUS', valeur: 'VIGUEUR' };

const sortie = [];
for (const item of $input.all()) {
  const article = item.json;
  // Une statistique (P3) ou une source secondaire ne produit jamais de règle.
  if (!['P1', 'P2'].includes(article.priorite)) continue;

  const r = article.recherche ?? {};
  let champs, filtres, fond, typePagination, cible;
  if (r.type === 'article_code') {
    champs = [critere('NUM_ARTICLE', r.article)];
    filtres = [{ facette: 'NOM_CODE', valeurs: [r.code] }, dateVersion];
    fond = 'CODE_DATE'; typePagination = 'ARTICLE'; cible = 'article';
  } else if (r.type === 'article_texte') {
    champs = [critere('NUM', r.numero), critere('NUM_ARTICLE', r.article)];
    filtres = [dateVersion];
    fond = 'LODA_DATE'; typePagination = 'DEFAUT'; cible = 'article';
  } else if (r.type === 'texte') {
    champs = [critere('NUM', r.numero)];
    filtres = [dateVersion, enVigueur];
    fond = 'LODA_ETAT'; typePagination = 'DEFAUT'; cible = 'texte';
  } else if (r.type === 'texte_nor') {
    champs = [critere('NOR', r.nor)];
    filtres = [dateVersion, enVigueur];
    fond = 'LODA_ETAT'; typePagination = 'DEFAUT'; cible = 'texte';
  } else if (r.type === 'texte_par_date') {
    champs = [critere('TITLE', r.titre)];
    filtres = [{ facette: 'DATE_SIGNATURE', dates: { start: r.date_signature, end: r.date_signature } }, dateVersion, enVigueur];
    fond = 'LODA_ETAT'; typePagination = 'DEFAUT'; cible = 'texte';
  } else {
    throw new Error('articles_suivis.json : type de recherche inconnu pour ' + article.cle);
  }

  sortie.push({
    json: {
      ...article,
      cible,
      date_ms: maintenant,
      corps_recherche: {
        recherche: { champs, filtres, pageNumber: 1, pageSize: 10, operateur: 'ET', sort: 'PERTINENCE', typePagination },
        fond,
      },
    },
  });
}
return sortie;

// Associe chaque réponse de recherche à son texte, puis retient l'identifiant Légifrance.
// La forme exacte de la réponse n'est pas décrite dans les exemples officiels : on y cherche
// les identifiants par leur format, et on ne retient un résultat que s'il est unique.
const articles = $("02 · Construire la recherche").all();
const reponses = $input.all();

function identifiants(valeur, motif, trouves = new Set()) {
  if (typeof valeur === 'string') { if (motif.test(valeur)) trouves.add(valeur); }
  else if (Array.isArray(valeur)) valeur.forEach((element) => identifiants(element, motif, trouves));
  else if (valeur && typeof valeur === 'object') Object.values(valeur).forEach((element) => identifiants(element, motif, trouves));
  return trouves;
}

return articles.map((item, i) => {
  const { corps_recherche, ...article } = item.json;
  const reponse = reponses[i] ? reponses[i].json : {};
  const statut = typeof reponse.statusCode === 'number' ? reponse.statusCode : null;

  let etat = 'trouve';
  let identifiant = null;
  let candidats = [];
  if (statut !== 200) {
    etat = 'source_indisponible';
  } else {
    let ids;
    if (article.cible === 'article') {
      ids = [...identifiants(reponse.body, /^LEGIARTI\d{12}$/)];
    } else {
      // Texte entier : la version consolidée (LEGITEXT) d'abord, sinon le texte du Journal officiel.
      ids = [...identifiants(reponse.body, /^LEGITEXT\d{12}$/)];
      if (ids.length === 0) ids = [...identifiants(reponse.body, /^JORFTEXT\d{12}$/)];
    }
    if (ids.length === 1) identifiant = ids[0];
    else if (ids.length === 0) etat = 'introuvable';
    else { etat = 'ambigu'; candidats = ids.slice(0, 10); } // jamais deviné : à préciser dans la liste
  }

  return { json: { ...article, etat, trouve: etat === 'trouve', identifiant, candidats, statut_recherche: statut } };
});

// Associe chaque lecture à son texte et en tire une version comparable d'une semaine à l'autre.
const articles = $("Texte trouvé ?").all(0); // sortie « vrai »
const reponses = $input.all();

function empreinte(texte) {
  let h = '';
  for (let k = 0; k < 2; k++) {
    let x = 0x811c9dc5;
    const s = k + ':' + texte;
    for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
    h += x.toString(16).padStart(8, '0');
  }
  return h;
}
function identifiants(valeur, motif, trouves = new Set()) {
  if (typeof valeur === 'string') { if (motif.test(valeur)) trouves.add(valeur); }
  else if (Array.isArray(valeur)) valeur.forEach((element) => identifiants(element, motif, trouves));
  else if (valeur && typeof valeur === 'object') Object.values(valeur).forEach((element) => identifiants(element, motif, trouves));
  return trouves;
}

return articles.map((item, i) => {
  const article = item.json;
  const reponse = reponses[i] ? reponses[i].json : {};
  const statut = typeof reponse.statusCode === 'number' ? reponse.statusCode : null;
  if (statut !== 200 || !reponse.body || typeof reponse.body !== 'object') {
    return { json: { ...article, etat: 'source_indisponible', trouve: false, statut_lecture: statut } };
  }

  let version, date_debut = null, etat_juridique = null, url_legifrance;
  if (article.cible === 'article') {
    const fiche = reponse.body.article && typeof reponse.body.article === 'object' ? reponse.body.article : reponse.body;
    // L'identifiant LEGIARTI change à chaque nouvelle version d'un article.
    version = article.identifiant;
    date_debut = fiche.dateDebut ?? null;
    etat_juridique = fiche.etat ?? null;
    const chemin = article.recherche.type === 'article_code' ? 'codes' : 'loda';
    url_legifrance = 'https://www.legifrance.gouv.fr/' + chemin + '/article_lc/' + article.identifiant;
  } else {
    // Texte entier : empreinte de la liste de ses articles en vigueur.
    const ids = [...identifiants(reponse.body, /^LEGIARTI\d{12}$/)].sort();
    version = 'empreinte:' + empreinte(ids.length > 0 ? ids.join(',') : JSON.stringify(reponse.body));
    url_legifrance = 'https://www.legifrance.gouv.fr/loda/id/' + article.identifiant;
  }

  return { json: { ...article, etat: 'lu', version, date_debut, etat_juridique, url_legifrance, statut_lecture: statut } };
});

// Compare la version lue à la version enregistrée dans le nœud Article du graphe.
const textes = $("Rassembler les textes").all().map((item) => item.json);

// Nœuds du graphe : corps de la lecture Supabase quand le nœud 07 est actif, sinon rien.
const lecture = $input.first().json;
const noeuds = Array.isArray(lecture.body) ? lecture.body : null;
const articlesEnregistres = new Map(
  (noeuds ?? []).filter((n) => n.type === 'Article' && n.proprietes && n.proprietes.cle).map((n) => [n.proprietes.cle, n]),
);

const compares = textes.map((texte) => {
  let changement;
  let version_enregistree = null;
  if (texte.etat !== 'lu') changement = texte.etat; // introuvable, ambigu, source_indisponible
  else if (noeuds === null) changement = 'non_compare'; // Supabase non branché
  else {
    const enregistre = articlesEnregistres.get(texte.cle);
    if (!enregistre) changement = 'premiere_lecture';
    else {
      version_enregistree = enregistre.proprietes.version ?? null;
      changement = version_enregistree === texte.version ? 'inchange' : 'modifie';
    }
  }
  return { ...texte, changement, version_enregistree };
});

return [{ json: { textes: compares, noeuds_graphe: noeuds } }];

// Une version modifiée (ou lue pour la première fois) crée une NOUVELLE ligne regles au
// statut « proposee ». Une règle existante n'est jamais modifiée : les diagnostics passés
// gardent leur version.
const { textes, noeuds_graphe } = $("08 · Comparer les versions").first().json;

// Règles : corps de la lecture Supabase quand le nœud 09 est actif, sinon rien.
const lecture = $input.first().json;
const regles = Array.isArray(lecture.body) ? lecture.body : null;
const aujourdhui = new Date().toISOString().slice(0, 10);

// Regroupe par règle les textes à proposer.
const parCode = new Map();
const sans_regle = [];
for (const texte of textes) {
  if (!['modifie', 'premiere_lecture'].includes(texte.changement)) continue;
  if (!['P1', 'P2'].includes(texte.priorite)) continue; // jamais de règle depuis une statistique
  if (!Array.isArray(texte.regles) || texte.regles.length === 0) {
    sans_regle.push({ cle: texte.cle, reference: texte.reference, changement: texte.changement, version: texte.version });
    continue;
  }
  for (const code of texte.regles) {
    if (!parCode.has(code)) parCode.set(code, []);
    parCode.get(code).push(texte);
  }
}

const propositions = [];
const non_proposees = [];
for (const [code, sources] of parCode) {
  const versions = (regles ?? []).filter((r) => r.code === code);
  if (versions.length === 0) {
    non_proposees.push({ code, motif: regles === null ? 'Supabase non branché' : 'règle absente de la table regles' });
    continue;
  }
  const derniere = versions.reduce((max, r) => (r.version > max.version ? r : max));
  // La source porte, pour chaque texte, sa clé et la version lue : « référence (cle@version) ».
  const source_ref = sources.map((s) => s.reference + ' (' + s.cle + '@' + s.version + ')').join(' ; ');
  if (versions.some((r) => r.source_ref === source_ref)) continue; // déjà proposée ou validée pour ces versions
  propositions.push({
    code,
    version: derniere.version + 1,
    intitule: derniere.intitule,
    element: derniere.element,
    force: derniere.force,
    verdict_type: derniere.verdict_type,
    source_id: derniere.source_id,
    source_ref,
    source_url: sources[0].url_legifrance,
    statut_validation: 'proposee', // la validation est un geste humain, hors de ce workflow
    verifie_le: aujourdhui,
    relu_par: null,
  });
}

return [{ json: { textes, noeuds_graphe, regles, propositions, sans_regle, non_proposees } }];

// Identifiant déterministe au format UUID (version 8) : rejouer le workflow réécrit les mêmes lignes.
function idDeterministe(texte) {
  let h = '';
  for (let k = 0; k < 4; k++) {
    let x = 0x811c9dc5;
    const s = k + ':' + texte;
    for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
    h += x.toString(16).padStart(8, '0');
  }
  const variante = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-8' + h.slice(13, 16) + '-' + variante + h.slice(17, 20) + '-' + h.slice(20, 32);
}

// VALIDATION HUMAINE BLOQUANTE : seules les règles au statut « validee » sont publiées.
// Ce workflow ne passe jamais une règle de « proposee » à « validee ».
const { textes, noeuds_graphe, regles } = $("10 · Préparer les règles proposées").first().json;
const lignes = new Map();
const journal = [];

if (Array.isArray(regles) && Array.isArray(noeuds_graphe)) {
  const codeDe = new Map(regles.map((r) => [r.id, r.code]));
  const versionLue = new Map(textes.filter((t) => t.etat === 'lu').map((t) => [t.cle, t]));
  const articles = new Map(noeuds_graphe.filter((n) => n.type === 'Article' && n.proprietes && n.proprietes.cle).map((n) => [n.proprietes.cle, n]));

  // Dernière version VALIDÉE de chaque règle.
  const validees = new Map();
  for (const r of regles) {
    if (r.statut_validation !== 'validee') continue;
    const courante = validees.get(r.code);
    if (!courante || r.version > courante.version) validees.set(r.code, r);
  }

  for (const regle of validees.values()) {
    // 1. Le nœud Règle pointe vers la dernière version validée.
    for (const noeud of noeuds_graphe.filter((n) => n.type === 'Regle' && codeDe.get(n.regle_id) === regle.code)) {
      if (noeud.regle_id === regle.id) continue;
      lignes.set(noeud.id, {
        id: noeud.id, type: 'Regle', libelle: noeud.libelle, contrat_id: null, regle_id: regle.id,
        proprietes: { ...(noeud.proprietes ?? {}), code: regle.code, version: regle.version, source_ref: regle.source_ref, source_url: regle.source_url },
      });
      journal.push({ noeud: 'Regle', code: regle.code, version: regle.version });
    }
    // 2. Le nœud Article enregistre la version validée, si c'est bien celle lue aujourd'hui.
    for (const [, cle, version] of String(regle.source_ref ?? '').matchAll(/\(([a-z0-9-]+)@([^)]+)\)/g)) {
      const lu = versionLue.get(cle);
      const existant = articles.get(cle);
      if (!lu || lu.version !== version) continue; // le texte a encore changé : attendre la prochaine proposition
      if (existant && existant.proprietes.version === version) continue;
      const id = existant ? existant.id : idDeterministe('Article|' + cle);
      lignes.set(id, {
        id, type: 'Article', libelle: lu.reference, contrat_id: null, regle_id: null,
        proprietes: { ...(existant ? existant.proprietes : {}), cle, version, date_verification: regle.verifie_le, url_legifrance: lu.url_legifrance },
      });
      journal.push({ noeud: 'Article', cle, version });
    }
  }
}

return [{ json: { lignes: [...lignes.values()], journal } }];

// Bilan lisible de l'exécution. Aucun envoi automatique.
const p = $("10 · Préparer les règles proposées").first().json;
const publication = $("12 · Préparer la publication").first().json;
const compter = (changement) => p.textes.filter((t) => t.changement === changement).length;
const lister = (changement) => p.textes.filter((t) => t.changement === changement).map((t) => ({ cle: t.cle, reference: t.reference, candidats: t.candidats && t.candidats.length > 0 ? t.candidats : undefined }));

return [{
